  id_usuariomodificacion varchar(12), 
  fecha_modificacion date, 
  id_comprafact numeric CONSTRAINT FK_NOTA_COMPRA_COMPRA REFERENCES COMPRA_FACT(id_comprafact), 
  afecta_caja varchar(1), 
  id_documentoidentidad varchar(10), 
  ajuste_precio varchar(1), 
  tipo_cambio decimal(10,4), 
