, parcial_presupuesto decimal(18,4), costo_directo_val  decimal(10,2), porcentaje_gasto_val  decimal(10,4), porcentaje_gastootro_val  decimal(10,4), porcentaje_utilidad_val  decimal(10,4), porcentaje_igv_val decimal(10,4), porcentaje_impuestootro_val  decimal(10,4), factor_valorizacion decimal(10,5), monto_gastootro_val decimal(18,4), otros_costos_directos decimal(18,4));

