CREATE TABLE titulo_supervision (
id_titulo  CHAR(12) NOT NULL,
descripcion_titulo  VARCHAR(255),
id_titulopadre  CHAR(12),
posicion_titulo  INT,
id_presupuesto  CHAR(12),
estado_expandido  CHAR(1),
numeracion_titulo  VARCHAR(120),
costo_titulo  decimal(18,4),
estado_bloqueado  CHAR(1), 
color_fuente numeric, nombre_fuente varchar(100), 
