PRIMARY KEY (id_titulo)
);

CREATE TABLE costo_unitariosupervision (
id_costounitario CHAR(12) NOT NULL,
descripcion_costo VARCHAR(120),
id_unidad CHAR(12),
costo_unitario NUMERIC(16, 2),
tiempo_requerido NUMERIC(16, 2),
id_unidadtiempo CHAR(12),
id_titulo CHAR(12),
numeracion_costo VARCHAR(120),
posicion_costo INTEGER,
cantidad NUMERIC(16, 2),
parcial_costo NUMERIC(16, 2),
tiene_composicion CHAR(1),
cadena_tiempo varchar(255), 
color_fuente numeric, 
nombre_fuente varchar(100), 
estilo_fuente int, 
tamano_fuente decimal(6,2), 
color_fondo numeric,
PRIMARY KEY(id_costounitario)
);

CREATE TABLE titulo_bim (
id_titulo CHAR(12) NOT NULL,
descripcion_titulo VARCHAR(255),
id_titulopadre CHAR(12),
posicion_titulo INTEGER,
id_proyecto CHAR(12),
estado_expandido CHAR(1),
color_fuente numeric, 
nombre_fuente varchar(100), 
estilo_fuente int, 
tamano_fuente decimal(6,2), 
color_fondo integer,
bim_guid varchar(128), id_unidad char(12), cantidad decimal(18,2), parcial_costo decimal(18,2), es_entidad char(1), check_cantidad char(1), check_largo char(1), check_ancho char(1), check_alto char(1), check_peso char(1), check_area char(1), check_volumen char(1),
PRIMARY KEY(id_titulo)
);

CREATE TABLE metrado_bim (
id_metrado CHAR(12) NOT NULL,
descripcion_metrado VARCHAR(255),
posicion int,
id_titulo CHAR(12),
unidades NUMERIC(16, 2),
cantidadxunidad NUMERIC(16, 2),
largo NUMERIC(16, 2),
ancho NUMERIC(16, 2),
alto NUMERIC(16, 2),
peso NUMERIC(16, 2),
area NUMERIC(16, 2),
volumen NUMERIC(16, 2),
parcial_metrado NUMERIC(16, 2),
observaciones VARCHAR(255),
color_fuente numeric, nombre_fuente varchar(100), estilo_fuente int, tamano_fuente decimal(6,2), color_fondo numeric,
propiedad_largo varchar(150),
propiedad_ancho varchar(150),
propiedad_alto varchar(150),
propiedad_peso varchar(150),
propiedad_area varchar(150),
propiedad_volumen varchar(150),
bim_guid varchar(128),
PRIMARY KEY(id_metrado)
);

CREATE TABLE programacion_metrado
(
  id_programacion integer constraint pk_programacion_metrado primary key autoincrement,  
  fecha_inicio date,
  fecha_fin date,  
  cantidad decimal(10,2),  
  id_metrado char(12) constraint fk_programacion_metrado references metrado_bim(id_metrado)
  
, avance decimal(10,2));


